#!/bin/sh
# Build the busycoq halting proof of 1RB1RA_1LC0RD_1LD1LB_1LE0LF_0RA---_0LB0LE (bbchallenge 181655).
# usage: sh build.sh /path/to/busycoq
#   (a checkout of the BB6 branch of https://github.com/ccz181078/busycoq, tested at 33209bc: the proof uses its
#   Individual62.v)
# Needs Coq 8.18 or later (tested with 8.18.0). About 45 to 110 minutes, nearly all of it the final evaluation run_ok.
# H181655.v is generated by tools/coq/t4engine/proof/build.sh; this script only compiles it. The file ends with
# Print Assumptions halt.
set -e
BC=${1:?give the path of a busycoq checkout (BB6 branch)}
HERE=$(cd "$(dirname "$0")" && pwd)
V="$BC/verify"
cp "$HERE"/H181655.v "$V"/
cd "$V"
[ -f Makefile.coq ] || make Makefile.coq > /dev/null
make -f Makefile.coq Individual62.vo > /dev/null 2>&1
t0=$(date +%s)
coqc -Q . BusyCoq H181655.v
echo "compiled in $(( $(date +%s) - t0 )) s"
